visibles incluso móvil. Oferta permanente aun sin oferta, Pagos contexto carta, Documentos repositorio persistente de Carta de No Adeudo, destino habilitado solo ruta y pantalla canónicas. No usar Mis operaciones, elegibilidad, estado normalizado como etiquetas de navegación permanente; no altera CTA de éxito aprobado. Contraste mínimo {param:UX.AUTH_NAV_LABEL_MIN_CONTRAST_RATIO}. applicability_v1 UNRESOLVED, no inferir pantalla ni habilitar runtime. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/589","solicitante":"Cristhian / Claude S22-AX"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ax_auth_navigation_release"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ax_nav_items_wrong"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ax_nav_label_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_offer_hidden"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_route_not_canonical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_document_not_retained"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_contextual_payment_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_forbidden_terms"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_nav_icon_only"},"der":{"lit":true}}},"der":{"op":"<","izq":{"hecho":"ax_nav_label_contrast"},"der":{"param":"UX.AUTH_NAV_LABEL_MIN_CONTRAST_RATIO"}}}},"pruebas":[{"entrada":{"ax_auth_navigation_release":true,"ax_nav_items_wrong":false,"ax_nav_label_missing":false,"ax_nav_offer_hidden":false,"ax_nav_route_not_canonical":false,"ax_nav_document_not_retained":false,"ax_nav_contextual_payment_missing":false,"ax_nav_forbidden_terms":false,"ax_nav_icon_only":false,"ax_nav_label_contras