22AX-592-1","clave":"s22ax_legacy_592_0","familia":"ROLLOUT_PRODUCTION_GATES","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Activación comercial de Beneficios LF separada de desarrollo","descripcion":"BLOQUEAR activación comercial por componente cuando validaciones pre-lanzamiento aplicables Legal y Economics/unit economics no resueltas. Desarrollo, diseño y QA continúan en paralelo; rechazo legal mantiene apagado, observación económica ajustar configuración/pricing/alcance o mantener apagado. ADR-LF-BEN-001; screen_binding DEFER_UNTIL_CANONICAL_SCREEN_REVIEW y applicability_v1 UNRESOLVED, no inferir pantalla ni consumidor. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/592","solicitante":"Cristhian / Claude S22-AX"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ax_benefit_commercial_activation"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ax_dev_status_authorizes_commercial"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ax_prelaunch_validation_unresolved"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_legal_rejection_active"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_economic_observation_unresolved"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ax_benefit_commercial_activation":true,"ax_dev_status_authorizes_commercial":false,"ax_prelaunch_validation_unresolved":false,"ax_legal_rejection_active":false,"ax_economic_observation_unresolved":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ax_benefit_commercial_activation":true,"ax_dev_status_authorizes_commercial":true,"ax_prelaunch_validation_unresolved":false,"ax_legal_rejection_active":false,"ax_economic_observation_unresolved":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ax_benefit_com