","titulo":"Trazabilidad de cambios de Beneficios LF","descripcion":"BLOQUEAR cambio de activación, parámetros, vigencia o alcance de Beneficios LF fuera de flujo administrativo server-side autorizado, configuración canónica y trazabilidad efectiva. Cliente final nunca autoridad comercial. ADR-LF-BEN-001; no inventar roles, permisos, registro auditoría ni pantalla; screen_binding DEFER_UNTIL_CANONICAL_SCREEN_REVIEW y applicability_v1 UNRESOLVED se conservan. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/596","solicitante":"Cristhian / Claude S22-AX"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ax_benefit_config_change"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ax_benefit_config_not_canonical"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ax_benefit_change_unauthorized"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_benefit_change_no_audit"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_client_modifies_commercial_config"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ax_benefit_binding_invented"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ax_benefit_config_change":true,"ax_benefit_config_not_canonical":false,"ax_benefit_change_unauthorized":false,"ax_benefit_change_no_audit":false,"ax_client_modifies_commercial_config":false,"ax_benefit_binding_invented":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ax_benefit_config_change":true,"ax_benefit_config_not_canonical":true,"ax_benefit_change_unauthorized":false,"ax_benefit_change_no_audit":false,"ax_client_modifies_commercial_config":false,"ax_benefit_binding_invented":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ax_benefit_config_change":true,"ax_benefit_config_not_canonical":false,"ax_benefit_change_unauthorized":true,"ax